"""Compares what code_compiler/source/builtins.inc says about each function with how the original registers it.

Needs the originals in /third_party. Prints every function where the number of arguments, their types, the ones that can be
left out or the type of the result is not the same. This is only a hint: the original has a type for strings that
the table spells differently, and some functions are on purpose a bit different.
"""
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import suite_functions as sf  # noqa: E402

ROW = re.compile(r'\{\s*"([a-z0-9_]+)"\s*,\s*"([a-z0-9_]+)"\s*,\s*\'(.)\'\s*,\s*"([a-z]*)"\s*,\s*(\d+)\s*,\s*\{([^}]*)\}')
KIND = {"%": "i", "#": "f", "$": "s", "!": "l"}


def parse_original(signature):
    result = KIND.get(signature[:1], "v")
    body = signature[1:] if signature[:1] in KIND else signature
    body = re.sub(r"^[A-Za-z_][A-Za-z0-9_]*", "", body)
    kinds, required = "", 0
    for kind, name, default in re.findall(r"([%#$!])([A-Za-z_][A-Za-z0-9_]*)(=[^%#$!]*)?", body):
        kinds += KIND[kind]
        if not default:
            required += 1
    return result, kinds, required


def main():
    text = open(os.path.join(sf.ROOT, "code_compiler", "source", "builtins.inc")).read()
    ours = {m.group(1): (m.group(3), m.group(4), int(m.group(5))) for m in ROW.finditer(text)}
    problems = 0
    for name, (module, signature) in sorted(sf.originals().items()):
        if name not in ours:
            continue
        result, kinds, required = parse_original(signature)
        our_result, our_kinds, our_required = ours[name]
        # Some of the original's functions take things we spell as other letters: handles are integers.
        if (result, kinds, required) != (our_result, our_kinds, our_required):
            print("%-22s original %s(%s) with %d required, here %s(%s) with %d required   [%s]" % (
                name, result, kinds, required, our_result, our_kinds, our_required, signature))
            problems += 1
    print("%d differences" % problems)


if __name__ == "__main__":
    main()
